def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    horse_patches = image_patch.find("horse")

    if not horse_patches:
        return image_patch

    max_face_angle = -math.inf
    target_horse = None

    for horse in horse_patches:
        face_direction = horse.llm_query("In what direction is the horse looking?", long_answer=False).strip().lower()
        if "camera" in face_direction:
            return horse

        angle = abs(face_direction.split()[0])
        if angle > max_face_angle:
            max_face_angle = angle
            target_horse = horse

    return target_horse

